    this._boundPlay = this.playEvent.bind(this);
    this._boundPause = this.pauseEvent.bind(this);
    this._boundEnded = this.endedEvent.bind(this);
    this._boundError = this.errorEvent.bind(this);
    this._boundWaiting = this.waitingEvent.bind(this);
    this._boundCanplay = this.canplayEvent.bind(this);
    this._boundLoadedmetadata = this.loadedmetadataEvent.bind(this);
    this._boundLoadstart = this.loadstartEvent.bind(this);
    this._boundTimeupdate = this.timeupdateEvent.bind(this);
    this._boundDurationchange = this.durationchangeEvent.bind(this);
    this._boundVolumechange = this.volumechangeEvent.bind(this);
    this._boundSeeked = this.seekedEvent.bind(this);
    this.options = options;
    this.parent = parent;
